I've written some naive implementation of matrix operations to measure the performance impact of jax on non-numpy code and obtained different results when using jax (either using jit or value_and_grad):
import jax.numpy as np
from jax import jit

def make_mat(m, n):
  a = []
  for i in range(0, m):
    a.append([])
    for j in range(0, n):
      a[i].append(0)
  return a

def mat_mul(a, b):
  m = len(a)
  n = len(b[0])
  c = make_mat(m, n)
  for i in range(0, m):
    for j in range(0, n):
      for k in range(0, len(b)):
        c[i][j] += a[i][k] * b[k][j]
  return c

def trace(m):
  tot = 0
  for i in range(0, len(m)):
    tot += m[i][i]
  return tot

def transpose(m):
  a = make_mat(len(m[0]), len(m))
  for i in range(0, len(m)):
    for j in range(0, len(m[0])):
      a[j][i] = m[i][j]
  return a

def f(v):
  v = [v]
  #print(v)
  m = mat_mul(transpose(v), v)
  #print(m)
  mm = mat_mul(m, m)
  #print(mm)
  return trace(mm)

v = [float(n-5) for n in range(0, 30)]

print(f(v))
print(jit(f)(v))
It prints 24552025.0 for the vanilla python version and 24552024.0 for the jit version.

