When batching a dot_general primitive, the batch axis is moved to the end of the array. Right now, this can cause problems for high-rank tensors because the order of axes affects the way XLA compiles the operation (in particular, can result in padding out the moved batched axis to a multiple of 128, instead of using one of the other larger axes).
Instead of moving the batch axis to the end, it should be possible to keep it in its original location, which would give the user more control over how XLA compiles the computation.
A repro that produces this behavior:
x = jnp.zeros((16, 3, 256, 256))
y = jnp.zeros((2, 4, 256))
z = jnp.zeros((16, 3, 4, 256, 2048))

def go(x, y, z):
  return jnp.einsum("vnn,sn,vsnj->nj", x, y, z)

@jax.jit
def repro(x, y, z):
  go_bat = jax.vmap(jax.vmap(go, (0, None, 0)), (None, 0, None))
  return go_bat(x, y, z)

repro(x, y, z)

I'm attempting to make a simple Object Oriented interface for MLP using Jax.  When following the documentation for the stax dropout it says that a PRNGkey must be an argument in the apply_function.  All layers pass **kwargs to the __call__ function so that akey is available for the dropout layer.
Training over batches means also passing batches of PRNGkeys to the __call__ function of the Net.  The training cycle takes 4x longer using this implementation compared to a version without dropout (i.e. no **kwargs, no batched keys).
Is this the right way to implement Dropout?  Am I missing some subtlety about vmap, jit, or grad that is causing this slowdown.
Any advice or feedback would be helpful.
from typing import Any, List, Tuple

import jax.numpy as np
from jax import jit, nn, random

from .base import PyTreeLike
from .tensor import Tensor

class Layer(PyTreeLike, is_abstract=True):
    """Abstract Class for Layers. Enforces subclasses to implement
    __call__, tree_flatten, tree_unflatten and registered as Pytree"""

    def __call__(self, inputs: Tensor, **kwargs) -> Tensor:
        raise NotImplementedError


class ActivationLayer(Layer, is_abstract=True):
    """Abstract Class for Activation Layers."""

    def tree_flatten(self) -> Tuple[List[None], None]:
        return ([None], None)

    @classmethod
    def tree_unflatten(cls, aux: Any, data: Iterable[Any]) -> "ActivationLayer":
        return cls()

class Linear(Layer):
    """Dense Linear Layer.
    Computes output = np.dot(w, inputs) + b"""

    def __init__(self, w: Tensor, b: Tensor) -> None:
        self.w = w
        self.b = b

    @jit
    def __call__(self, inputs: Tensor, **kwargs) -> Tensor:
        """outputs = np.dot(w, inputs) + b in single instance notation."""

        return np.dot(self.w, inputs) + self.b

    def tree_flatten(self) -> Tuple[Tuple[Tensor, Tensor], None]:
        return ((self.w, self.b), None)

    @classmethod
    def tree_unflatten(cls, aux: Any, params: Tuple[Tensor, Tensor]) -> "Linear":
        return cls(*params)


class Dropout(Layer):
    """Dropout Layer. If in train mode, keeps input activations at given probability rate,
    otherwise returns inputs directly"""

    def __init__(self, keep: float = 0.8, mode: str = "train"):
        self.keep = keep
        self.mode = mode

    @jit
    def __call__(self, inputs: Tensor, **kwargs) -> Tensor:
        """If in train mode, keeps input activations at rate,
        otherwise returns directly"""

        if self.mode == "eval":
            return inputs

        key = kwargs.get("key", None)
        if key is None:
            msg = (
                "Dropout layer requires __call__ to be called with a PRNG key "
                "argument. That is, instead of `dropout(inputs)`, call "
                "it like `dropout(inputs, key)` where `key` is a "
                "jax.random.PRNGKey value."
            )
            raise ValueError(msg)
        mask = random.bernoulli(key, self.keep, inputs.shape)
        return np.where(mask, inputs / self.keep, 0)

    def tree_flatten(self) -> Tuple[List[None], Tuple[float, str]]:
        return ([None], (self.keep, self.mode))

    @classmethod
    def tree_unflatten(cls, aux: Tuple[float, str], params: List[Any]) -> "Dropout":
        return cls(*aux)


class Tanh(ActivationLayer):
    def __call__(self, inputs: Tensor, **kwargs) -> Tensor:
        return np.tanh(inputs)

class FeedForwardNet(Layer):
    """Class for feed forward nets like Multi-layer Perceptrons."""

    def __init__(self, layers: List[Layer]) -> None:
        self.layers = layers

    @jit
    def predict(self, vector_inputs: Tensor, key: Tensor) -> Tensor:
        """Predict for a single instance by iterating over all the layers"""
        for layer in self.layers:
            vector_inputs = layer(vector_inputs, key=key)
        return vector_inputs

    @jit
    def __call__(self, batched_inputs: Tensor, batched_keys: Tensor) -> Tensor:
        """Batched Predictions"""

        return vmap(self.predict)(batched_inputs, batched_keys)

    def tree_flatten(self) -> Tuple[List[Layer], None]:
        return self.layers, None

    @classmethod
    def tree_unflatten(cls, aux: Any, params: List[Layer]) -> "FeedForwardNet":

        return cls(params, aux)

Combining jit with pmap produces some undesirable and surprising behaviors.
As one example, any lazy intermediate constants used by the function get instantiated and copied to every device. For instance:
@jax.jit
@jax.pmap
def foo(x):
  z = jnp.zeros((500_000_000,))
  return jax.lax.tie_in(z, x)

foo(jnp.arange(16).reshape((8, 2)))

This causes 2GB of data to be allocated on each device (and, right now, if this is the only computation you run, this can be verified by looking at list(list(jax.pxla.parallel_callable.__closure__[1].cell_contents.items())[0][1].values())[-1][0].__closure__[0].cell_contents, but that might break).
Relatedly, the jit causes the return value to be copied back to a single host instead of staying as a ShardedDeviceArray.
Ideally, adding jit would not make behavior worse. But having a warning when such a situation occurs would also be useful here, since pmap on its own does the right thing.
